===== Invoice.java =====
package net.officefloor.hq.app;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/**
 * An invoice raised against a project: the id of the {@link Project} it belongs to and a money
 * amount. Mapped to the {@code invoice} table created by {@code V4__invoices.sql}. IDENTITY id so
 * the DB assigns it on insert (seed inserts explicit ids via JdbcTemplate; GENERATED BY DEFAULT
 * allows both).
 */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id")
    private Long projectId;

    private BigDecimal amount;

    /** Payment status: UNPAID by default, PAID once marked paid (see V5__invoice_status.sql). */
    private String status;

    /** The day the invoice went out, an ISO date literal (see V9__invoice_dates.sql). */
    @Column(name = "issued_date")
    private String issuedDate;

    /** The day the invoice is due, an ISO date literal (see V9__invoice_dates.sql). */
    @Column(name = "due_date")
    private String dueDate;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public void setProjectId(Long projectId) {
        this.projectId = projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getIssuedDate() {
        return issuedDate;
    }

    public void setIssuedDate(String issuedDate) {
        this.issuedDate = issuedDate;
    }

    public String getDueDate() {
        return dueDate;
    }

    public void setDueDate(String dueDate) {
        this.dueDate = dueDate;
    }
}
===== InvoicePay.java =====
package net.officefloor.hq.app;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * {@code POST /api/invoices/pay} — mark an invoice paid and return the updated row. Wired by
 * {@code officefloor/rest/api/invoices/pay.POST.yml}. The invoice must exist; flipping it to PAID is
 * recorded through {@link Audit} so the payment can be checked back later (the UI can't show it).
 */
public class InvoicePay {

    public void service(@RequestBody PayInvoice body, InvoiceRepository invoices, Audit audit,
            ObjectResponse<Invoice> response) {
        Long id = body.getId();
        Invoice invoice = id == null ? null : invoices.findById(id).orElse(null);
        if (invoice == null) {
            throw new IllegalArgumentException("no such invoice");
        }
        invoice.setStatus("PAID");
        Invoice saved = invoices.save(invoice);
        audit.record("INVOICE_PAID id=" + saved.getId() + " amount="
                + saved.getAmount().toPlainString());
        response.send(saved);
    }
}
===== InvoiceRepository.java =====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

/**
 * Data access for {@link Invoice}. A Spring Data bean, injected into the OfficeFloor logic classes
 * that back the /api/invoices routes.
 */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** All invoices, oldest first, so the list order is stable for the UI and tests. */
    List<Invoice> findAllByOrderByIdAsc();

    /**
     * All invoices, earliest due date first (id as a stable tiebreaker), backing the project
     * invoices' sort-by-due-date control.
     */
    List<Invoice> findAllByOrderByDueDateAscIdAsc();

    /**
     * The money still owed: the sum of every UNPAID invoice's amount, or 0 when none are unpaid.
     * Backs the dashboard's outstanding total ({@code GET /api/dashboard}).
     */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status = 'UNPAID'")
    BigDecimal sumUnpaidAmount();
}
